+interface SignedToken {
+  id: string;
+  userId: string;
+  issuedAt: number;
+  expiresAt: number;
+  signature: string;
+}
+
+const getSigningKey = (): string => {
+  const key = process.env.SESSION_SIGNING_KEY;
+  if (!key) throw new Error("SESSION_SIGNING_KEY environment variable required");
+  return key;
+};
+
+const TOKEN_TTL_MS = 5 * 60 * 1000; // 5 minutes for edge worker, tight enough for revocation
+
+export const signSessionToken = (session: Session): string => {
+  const now = Date.now();
+  const token: SignedToken = {
+    id: session.id,
+    userId: session.userId,
+    issuedAt: now,
+    expiresAt: now + TOKEN_TTL_MS,
+    signature: "",
+  };
+
+  const payload = JSON.stringify({
+    id: token.id,
+    userId: token.userId,
+    issuedAt: token.issuedAt,
+    expiresAt: token.expiresAt,
+  });
+
+  const hmac = createHmac("sha256", getSigningKey());
+  token.signature = hmac.update(payload).digest("hex");
+
+  return Buffer.from(JSON.stringify(token)).toString("base64");
+};
+
+export const verifySessionToken = (tokenString: string): Session | null => {
+  try {
+    const token: SignedToken = JSON.parse(
+      Buffer.from(tokenString, "base64").toString("utf-8"),
+    );
+
+    const now = Date.now();
+    if (token.expiresAt < now) return null;
+
+    const payload = JSON.stringify({
+      id: token.id,
+      userId: token.userId,
+      issuedAt: token.issuedAt,
+      expiresAt: token.expiresAt,
+    });
+
+    const hmac = createHmac("sha256", getSigningKey());
+    const expectedSignature = hmac.update(payload).digest("hex");
+
+    // Use timing-safe comparison to prevent timing attacks
+    if (!timingSafeEqual(Buffer.from(token.signature), Buffer.from(expectedSignature))) {
+      return null;
+    }
+
+    return {
+      id: token.id,
+      userId: token.userId,
+      revokedAt: null,
+    };
+  } catch {
+    return null;
+  }
+};
